export const TITLE_MAX_LENGTH = 500;

export class ValidationError extends Error {}

/** Characters that render as nothing: separators and invisible format characters (zero-width space, joiners, BOM...). */
const INVISIBLE_ONLY = /^[\p{Z}\p{Cf}]*$/u;
/** C0/C1 control characters. NUL in particular makes SQLite's length() stop early, defeating the CHECK. */
const CONTROL = /\p{Cc}/u;

/**
 * Returns the trimmed title to store, or throws a ValidationError saying what is wrong.
 * Length is counted in code points, the way SQLite's length() counts it, so the two never disagree.
 */
export function parseTitle(input: unknown): string {
  if (typeof input !== "string") throw new ValidationError("title must be a string");
  if (!input.isWellFormed()) throw new ValidationError("title must be valid Unicode text");

  const title = input.trim();
  if (title === "" || INVISIBLE_ONLY.test(title)) throw new ValidationError("title must not be empty");
  if (CONTROL.test(title)) throw new ValidationError("title must not contain control characters");

  const length = [...title].length;
  if (length > TITLE_MAX_LENGTH) {
    throw new ValidationError(`title must be at most ${TITLE_MAX_LENGTH} characters long`);
  }
  return title;
}

/** Reads the `title` of a decoded JSON body, which must be a plain object. */
export function parseCreateBody(body: unknown): { title: string } {
  if (typeof body !== "object" || body === null || Array.isArray(body)) {
    throw new ValidationError("body must be a JSON object");
  }
  return { title: parseTitle((body as Record<string, unknown>).title) };
}
